#!/usr/bin/env python3
"""Exercise native windows with deterministic old-format reports and real Qt input events."""
import argparse
import json
import os
from pathlib import Path
import subprocess
import sys


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--exe',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);parser.add_argument('--fixtures',type=Path,required=True);parser.add_argument('--hdc',type=Path);args=parser.parse_args()
    output=args.output.resolve();output.mkdir(parents=True,exist_ok=True);fixtures=args.fixtures.resolve()
    profile=output/'profile';profile.mkdir(exist_ok=True)
    settings={'sessionsDir':str(fixtures),'hdcPath':str(args.hdc.resolve()) if args.hdc else ''}
    (profile/'settings.json').write_text(json.dumps(settings),encoding='utf-8')
    report=lambda name:json.dumps(str(fixtures/name))
    steps=[]
    def add(name,**kwargs):steps.append(dict(name=name,**kwargs))
    add('main window',delay=700,eval='qa.activateApp();qa.nativePointer=true;root.raise();root.requestActivate();qa.hover(root.bodyItem,2,2)',wait='root.active',screenshot='main.png')
    add('main is centered',eval='var placement=qa.windowPlacement(root);qa.print(JSON.stringify(placement))',assert_='(placement.insideAvailableArea && Math.abs(placement.centerErrorX)<=1 && Math.abs(placement.centerErrorY)<=1) || (()=>{throw new Error(JSON.stringify(placement));})()')
    # Synthetic QMouseEvents bypass WM_NCHITTEST and cannot prove Windows
    # titlebar behavior. These gestures use SendInput on the native desktop.
    if sys.platform == 'win32':
        add('native titlebar drag',eval='var beforeTitlebar=[root.x,root.y];if(!qa.nativeTitlebarGesture(root,"drag")) throw new Error("Native input unavailable")',wait='!qa.nativeInputBusy',assert_='qa.nativeInputSucceeded && Math.abs(root.x-beforeTitlebar[0]-80)<=3 && Math.abs(root.y-beforeTitlebar[1]-50)<=3')
        add('native titlebar double click maximizes',eval='qa.nativeTitlebarGesture(root,"doubleClick")',wait='!qa.nativeInputBusy && root.visibility===4',assert_='qa.nativeInputSucceeded')
        add('native titlebar double click restores',eval='qa.nativeTitlebarGesture(root,"doubleClick")',wait='!qa.nativeInputBusy && root.visibility===2',assert_='qa.nativeInputSucceeded')
        add('extended titlebar strip drag',eval='var beforeStrip=[root.x,root.y];qa.nativeTitlebarGesture(root,"drag",38)',wait='!qa.nativeInputBusy',assert_='qa.nativeInputSucceeded && root.x>beforeStrip[0]+40 && root.y>beforeStrip[1]+20')
        add('restore main after native input',eval='root.x=beforeTitlebar[0];root.y=beforeTitlebar[1]')
    for page in ['watch','peak','snap','reports','settings']:
        add('navigate '+page,eval=f'root.go({json.dumps(page)})')
        add('render '+page,delay=160,screenshot=page+'.png')
    # macOS half-screen tiling must not be blocked by the main window minimum.
    for width,pages in [(756,['watch','peak','snap','reports','settings']),(720,['peak','reports'])]:
        for page in pages:
            add(f'narrow {width} {page}',eval=f'root.width={width};root.height=680;root.go({json.dumps(page)})')
            add(f'narrow layout {width} {page}',delay=160,
                assert_=f'root.width==={width} && qa.find(root,"nav-reports").width<=qa.find(root,"sidebar").width',
                screenshot=f'narrow-{width}-{page}.png')
    add('restore main size',eval='root.width=1280;root.height=820;root.go("watch")')
    add('prepare library resize',eval='root.go("reports")')
    add('library column follows full drag',delay=200,eval='var resizeTable=qa.find(root,"reportsTable");var resizeHeader=qa.find(resizeTable,"header-taskName");var oldWidth=resizeHeader.width;var edge=resizeHeader.mapToItem(resizeTable,resizeHeader.width-3,19);qa.drag(resizeTable,edge.x,edge.y,edge.x+120,edge.y)',assert_='resizeHeader===qa.find(resizeTable,"header-taskName") && Math.abs(resizeHeader.width-oldWidth-120)<1 && !resizeTable.resizingColumn && qa.find(resizeTable,"tableScroll").contentX===0')
    add('library resized rows and saved width match',delay=150,assert_='qa.find(resizeTable,"cell-taskName-0").width===resizeHeader.width && backend.uiPreference("reports.columns.v1",[])[0].width===resizeHeader.width',screenshot='library-resized.png')
    add('leave resized library',eval='root.go("settings")')
    add('restore library width from preferences',eval='root.go("reports")',wait='qa.find(root,"reportsTable")!==null',assert_='Math.abs(qa.find(root,"header-taskName").width-oldWidth-120)<1')
    add('reset library after resizing',eval='qa.find(root,"reportsTable").resetLayout();root.go("watch")')
    add('open trend',eval='backend.openReport('+report('Trend-1')+')',wait='root.childWindows.length===1')
    add('trend is centered',delay=150,eval='var placement=qa.windowPlacement(root.childWindows[0]);qa.print(JSON.stringify(placement))',assert_='(placement.insideAvailableArea && Math.abs(placement.centerErrorX)<=1 && Math.abs(placement.centerErrorY)<=1) || (()=>{throw new Error(JSON.stringify(placement));})()')
    if sys.platform == 'win32':
        add('activate report for native titlebar',eval='root.childWindows[0].raise();root.childWindows[0].requestActivate()',wait='root.childWindows[0].active')
        add('report native titlebar drag',eval='var reportPosition=[root.childWindows[0].x,root.childWindows[0].y];qa.nativeTitlebarGesture(root.childWindows[0],"drag")',wait='!qa.nativeInputBusy',assert_='qa.nativeInputSucceeded && Math.abs(root.childWindows[0].x-reportPosition[0]-80)<=3')
        add('report native double click maximizes',eval='qa.nativeTitlebarGesture(root.childWindows[0],"doubleClick")',wait='!qa.nativeInputBusy && root.childWindows[0].visibility===4')
        add('report native double click restores',eval='qa.nativeTitlebarGesture(root.childWindows[0],"doubleClick")',wait='!qa.nativeInputBusy && root.childWindows[0].visibility===2')
        add('restore report position',eval='root.childWindows[0].x=reportPosition[0];root.childWindows[0].y=reportPosition[1]')
    add('prepare trend capture',eval='var report=root.childWindows[0];report.raise();report.requestActivate();var plot=qa.find(report,"memoryPlot");qa.hover(report.bodyItem,2,2);')
    add('trend layout',delay=300,wait='report.active',assert_='plot.width>300 && plot.height>200 && qa.find(report,"statCards").height===86',window='report',screenshot='trend.png')
    add('zoom native chart',eval='qa.wheel(plot,plot.width/2,plot.height/2,400)',assert_='plot.rangeEnd-plot.rangeStart<plot.totalSpan')
    add('hover sample',eval='qa.hover(plot,plot.width*.6,plot.height*.5)',wait='qa.find(report,"chartTip").visible && qa.find(report,"chartTip").retained.items.length===14',window='report',screenshot='tooltip.png')
    add('enter tooltip',eval='var tip=qa.find(report,"chartTip");qa.hover(tip.contentItem,40,30)')
    add('tooltip remains enterable',delay=500,assert_='tip.visible && tip.retained.items.length===14 && tip.y>=plot.mapToItem(tip.parent,0,0).y')
    add('leave tooltip',eval='qa.hover(report.bodyItem,2,2)')
    add('tooltip dismissed',wait='!tip.visible',timeout=2500)
    add('expand chart',eval='qa.click(qa.find(report,"maximizeChart"),-1,-1)',wait='qa.find(report,"expandedChart").opened')
    add('expanded screenshot',delay=200,window='report',screenshot='chart-expanded.png')
    add('restore expanded chart',eval='qa.key(report,16777216)',wait='!qa.find(report,"expandedChart").opened')
    add('reset chart',eval='plot.resetView();qa.hover(plot,0,0)',assert_='plot.rangeStart===0 && plot.rangeEnd===plot.totalSpan')
    add('rename report',eval='backend.renameReport('+report('Trend-1')+',"Trend-1 重命名");',wait='report.meta.taskName==="Trend-1 重命名"')
    add('restore name',eval='backend.renameReport('+report('Trend-1')+',"Trend-1")',wait='report.meta.taskName==="Trend-1"')
    add('open snapshot',eval='backend.openReport('+report('Snapshot-1')+')',wait='root.childWindows.length===2')
    add('snapshot is centered',delay=150,eval='var placement=qa.windowPlacement(root.childWindows[1]);qa.print(JSON.stringify(placement))',assert_='(placement.insideAvailableArea && Math.abs(placement.centerErrorX)<=1 && Math.abs(placement.centerErrorY)<=1) || (()=>{throw new Error(JSON.stringify(placement));})()')
    add('snapshot',delay=200,window='root.childWindows[1]',screenshot='snapshot.png')
    paths=[str(fixtures/f'Trend-{i}') for i in range(1,5)]
    add('open four-report comparison',eval='backend.openCompare('+json.dumps(paths)+')',wait='root.childWindows.length===3')
    add('comparison is centered',delay=150,eval='var placement=qa.windowPlacement(root.childWindows[2]);qa.print(JSON.stringify(placement))',assert_='(placement.insideAvailableArea && Math.abs(placement.centerErrorX)<=1 && Math.abs(placement.centerErrorY)<=1) || (()=>{throw new Error(JSON.stringify(placement));})()')
    add('default side-by-side layout',assert_='root.childWindows[2].tab===1 && qa.find(root.childWindows[2],"pickedSplit").orientation===1 && qa.find(root.childWindows[2],"sampleCard-3")!==null && qa.find(root.childWindows[2],"differenceTable").columns.length===5',window='root.childWindows[2]',screenshot='compare-four-charts.png')
    add('comparison column follows full drag',eval='var resizeTable=qa.find(root.childWindows[2],"differenceTable");var resizeHeader=qa.find(resizeTable,"header-name");var oldWidth=resizeHeader.width;var otherWidth=qa.find(resizeTable,"header-v1").width;var edge=resizeHeader.mapToItem(resizeTable,resizeHeader.width-3,19);qa.drag(resizeTable,edge.x,edge.y,edge.x+100,edge.y)',assert_='resizeHeader===qa.find(resizeTable,"header-name") && Math.abs(resizeHeader.width-oldWidth-100)<1 && Math.abs(qa.find(resizeTable,"header-v1").width-otherWidth)<1 && qa.find(resizeTable,"tableScroll").contentX===0')
    add('comparison header and cells align',delay=150,assert_='qa.find(resizeTable,"cell-name-0").width===resizeHeader.width',window='root.childWindows[2]',screenshot='compare-resized.png')
    add('comparison minimum column width',eval='var edge=resizeHeader.mapToItem(resizeTable,resizeHeader.width-3,19);qa.drag(resizeTable,edge.x,edge.y,10,edge.y)',assert_='resizeHeader.width===70 && !resizeTable.resizingColumn')
    add('reset comparison after resizing',eval='resizeTable.resetLayout()')
    add('comparison sort ascending',eval='var sortTable=qa.find(root.childWindows[2],"differenceTable");var sortHeader=qa.find(sortTable,"header-v1");var originalOrder=sortTable.rows.map(r=>r.name).join();qa.click(sortHeader,sortHeader.width/2,19)',assert_='sortTable.sortKey==="v1" && !sortTable.descending && sortTable.sortedRows[0].fixed && sortTable.sortedRows.slice(2).every((r,i)=>sortTable.sortedRows[i+1].v1<=r.v1)')
    add('comparison sort descending',eval='qa.click(sortHeader,sortHeader.width/2,19)',assert_='sortTable.sortKey==="v1" && sortTable.descending && sortTable.sortedRows[0].fixed && sortTable.sortedRows.slice(2).every((r,i)=>sortTable.sortedRows[i+1].v1>=r.v1)')
    add('comparison restores default order',eval='qa.click(sortHeader,sortHeader.width/2,19)',assert_='sortTable.sortKey==="" && !qa.find(sortTable,"sortIndicator-v1").visible && sortTable.sortedRows.map(r=>r.name).join()===originalOrder')
    add('reach bottom miniature',eval='var miniWindow=root.childWindows[2];var miniViewport=qa.find(miniWindow,"miniScroll");miniViewport.contentItem.contentY=miniViewport.contentHeight-miniViewport.availableHeight')
    add('hover bottom miniature',delay=200,eval='var bottomCard=qa.find(miniWindow,"sampleCard-3");var bottomPlot=qa.find(bottomCard,"memoryPlot");var bottomTip=qa.find(bottomCard,"chartTip");qa.hover(bottomPlot,bottomPlot.width*.6,bottomPlot.height*.4)',wait='bottomTip.visible')
    add('bottom tooltip uses viewport space',assert_='bottomTip.height===bottomTip.implicitHeight && bottomTip.y>=bottomTip.topBoundary() && bottomTip.y+bottomTip.height<=bottomTip.parent.height-5 && bottomTip.y<bottomPlot.mapToItem(bottomTip.parent,0,0).y',window='miniWindow',screenshot='compare-bottom-tooltip.png')
    add('leave bottom tooltip',eval='qa.hover(miniWindow.bodyItem,2,2)',wait='!bottomTip.visible')
    add('wheel over miniature scrolls list',eval='var beforeMiniScroll=miniViewport.contentItem.contentY;var beforeRange=[bottomPlot.rangeStart,bottomPlot.rangeEnd];qa.wheel(bottomPlot,bottomPlot.width*.3,bottomPlot.height*.4,240)',wait='miniViewport.contentItem.contentY<beforeMiniScroll',assert_='bottomPlot.rangeStart===beforeRange[0] && bottomPlot.rangeEnd===beforeRange[1]')
    add('restore miniature scroll',eval='miniViewport.contentItem.contentY=0;qa.hover(miniWindow.bodyItem,2,2)',wait='!bottomTip.visible')
    add('absolute and delta share one line',eval='var inlineWindow=root.childWindows[2];var primary=qa.find(inlineWindow,"inlinePrimary-v1-0");var delta=qa.find(inlineWindow,"inlineDelta-v1-0")',assert_='primary.visible && delta.visible && primary.y===delta.y && delta.font.pixelSize<primary.font.pixelSize && delta.text.indexOf("%")<0 && delta.text.charAt(0)==="("')
    add('copy complete comparison image',eval='var exportWindow=root.childWindows[2];exportWindow.exportImage("copy")',wait='!exportWindow.exporting && qa.imageInfo().width>=2880',timeout=15000)
    add('complete image includes last category',eval='var copiedImage=qa.imageInfo();var exportRows=qa.find(exportWindow,"differenceTable").sortedRows;var lastCategory=exportRows[exportRows.length-1].name',assert_='copiedImage.height>exportWindow.height*2 && copiedImage.description.indexOf(lastCategory)>=0')
    image_path=json.dumps(str(output/'comparison-full.png'))
    add('saved image matches copied pixels',eval='var imageExporter=qa.find(exportWindow,"comparisonImageExporter");var saved=imageExporter.prepare(exportWindow.ordered,exportWindow.exportOptions()) && imageExporter.save(backend.toFileUrl('+image_path+'));imageExporter.clear()',assert_='saved && qa.imageInfo('+image_path+').hash===copiedImage.hash')
    add('select overlay comparison',eval='root.childWindows[2].tab=0',wait='qa.find(root.childWindows[2],"summaryTable")!==null')
    add('prepare comparison capture',delay=200,eval='var compare=root.childWindows[2];var comparisonPlot=qa.find(compare,"memoryPlot");qa.hover(compare.bodyItem,2,2)')
    add('overlay layout',delay=300,assert_='comparisonPlot.width>300 && comparisonPlot.height>150 && comparisonPlot.alignment==="peak" && compare.label(compare.reports[0])==="Trend-1"',window='compare',screenshot='compare-overlay.png')
    add('compact comparison',eval='var comparisonWidth=compare.width;var comparisonHeight=compare.height;compare.width=1024;compare.height=684')
    add('compact comparison keeps chart readable',delay=300,assert_='comparisonPlot.width>300 && comparisonPlot.height>150',window='compare',screenshot='compare-compact.png')
    add('restore comparison size',eval='compare.width=comparisonWidth;compare.height=comparisonHeight')
    add('peak alignment',eval='compare.alignment="peak";compare.metric="GL";',assert_='comparisonPlot.alignment==="peak" && comparisonPlot.metric==="GL"')
    add('end alignment',eval='compare.alignment="end";',assert_='comparisonPlot.totalSpan>=359')
    add('choose baseline C in report list',eval='var originalColors=compare.reports.map(r=>r.compareColor).join();var originalPicks=JSON.stringify(compare.picked);qa.click(qa.find(compare,"reportBaseline-2"),-1,-1)',wait='compare.baselineIndex===2')
    add('baseline moves first with stable identity',assert_='compare.ordered[0].meta.id==="Trend-3" && compare.label(compare.ordered[0])==="Trend-3" && compare.reports.map(r=>r.compareColor).join()===originalColors && JSON.stringify(compare.picked)===originalPicks && qa.find(compare,"baselinePicker")===null',window='compare',screenshot='compare-baseline-c.png')
    add('picked mode',eval='compare.tab=1')
    add('select a sample',delay=200,eval='var mini=qa.find(compare,"memoryPlot");qa.click(mini,mini.width*.35,mini.height*.4)',assert_='compare.selected(compare.ordered[0])!==123',window='compare')
    add('clear picked hover',eval='qa.hover(mini,0,0);qa.hover(compare.bodyItem,2,2)')
    add('picked screenshot',delay=300,wait='!qa.find(compare,"chartTip").visible',window='compare',screenshot='compare-picked.png')
    add('edit sample number',eval='var sampleInput=qa.find(compare,"sampleIndex-0");qa.click(sampleInput,-1,-1);sampleInput.remove(0,sampleInput.length);sampleInput.insert(0,"20");qa.key(compare,16777220)',assert_='compare.selected(compare.reports[0])===19')
    add('difference scroll keeps category fixed',eval='var differences=qa.find(compare,"differenceTable");var differenceScroll=qa.find(differences,"tableScroll");differenceScroll.contentX=200',assert_='Math.abs(qa.find(differences,"header-name").mapToItem(differences,0,0).x)<1 && differences.columns.length===5')
    add('reach fourth report',eval='var miniScroll=qa.find(compare,"miniScroll");miniScroll.contentItem.contentY=Math.max(0,miniScroll.contentHeight-miniScroll.availableHeight);qa.hover(compare.bodyItem,2,2)')
    add('fourth report screenshot',delay=300,window='compare',screenshot='compare-fourth-report.png')
    add('baseline remains selected',eval='miniScroll.contentItem.contentY=0;compare.toggleReport(compare.baseline)',assert_='compare.hiddenReports.length===0 && !qa.find(compare,"reportVisible-2").enabled')
    add('hide A removes its table column',eval='miniScroll.contentItem.contentY=qa.find(compare,"sampleCard-0").y;qa.click(qa.find(compare,"reportVisible-0"),-1,-1)',assert_='compare.activeReports.length===3 && compare.differenceColumns.length===4 && !compare.differenceColumns.some(c=>c.key==="v0") && compare.baselineIndex===2')
    add('hidden report excluded from export',eval='compare.exportImage("copy")',wait='!compare.exporting',assert_='qa.imageInfo().description.indexOf("Trend-1")<0 && qa.imageInfo().description.indexOf("Trend-3")>=0')
    add('restore report visibility',eval='qa.click(qa.find(compare,"reportVisible-0"),-1,-1)',assert_='compare.hiddenReports.length===0 && compare.differenceColumns.length===5')
    add('set baseline from chart card',eval='var picksBefore=JSON.stringify(compare.picked);miniScroll.contentItem.contentY=qa.find(compare,"sampleCard-1").y;qa.click(qa.find(compare,"setBaseline-1"),-1,-1)',wait='compare.baselineIndex===1')
    add('card baseline identity and selected point retained',assert_='compare.ordered[0]===compare.reports[1] && compare.differenceColumns[1].key==="v1" && qa.find(compare,"currentBaseline-1").visible && JSON.stringify(compare.picked)===picksBefore && compare.reports.map(r=>r.compareColor).join()===originalColors')
    add('snapshot comparison',eval='backend.openCompare('+json.dumps([str(fixtures/'Snapshot-1'),str(fixtures/'Snapshot-2')])+')',wait='root.childWindows.length===4')
    add('snapshot difference',delay=200,assert_='root.childWindows[3].differenceRows.length===14',window='root.childWindows[3]',screenshot='compare-snapshot.png')
    add('snapshot baseline moves first',eval='var snapshotComparison=root.childWindows[3];snapshotComparison.setBaseline(snapshotComparison.reports[1])',assert_='snapshotComparison.ordered[0]===snapshotComparison.reports[1] && snapshotComparison.differenceRows[0].d0<0 && qa.find(snapshotComparison,"snapshotSummary").visible && qa.find(snapshotComparison,"differenceTable").columns.length===3')
    add('snapshot decline filter',eval='var snapshotFilter=qa.find(snapshotComparison,"snapshotDifferenceFilter");qa.click(snapshotFilter,-1,-1);qa.key(snapshotComparison,16777237);qa.key(snapshotComparison,16777237);qa.key(snapshotComparison,16777220)',wait='snapshotComparison.snapshotFilter===2',assert_='qa.find(snapshotComparison,"differenceTable").rows.every(r=>r.fixed || r.delta<0)',window='snapshotComparison',screenshot='snapshot-declines.png')
    add('restore snapshot baseline and filter',eval='snapshotComparison.baselineIndex=0;snapshotComparison.snapshotFilter=0')
    add('activate snapshot for responsive checks',eval='root.childWindows[1].width=1280;root.childWindows[1].raise();root.childWindows[1].requestActivate()',wait='root.childWindows[1].active')
    add('wide snapshot shows both charts',delay=200,eval='var snapshotWindow=root.childWindows[1];var snapBody=qa.find(snapshotWindow,"snapshotBody");var snapshotScroll=qa.find(snapshotWindow,"snapshotScroll");var categoryTable=qa.find(snapshotWindow,"snapshotCategoryTable");var categoryRows=qa.find(categoryTable,"tableRows");snapshotWindow.raise();snapshotWindow.requestActivate()',assert_='snapBody.sideBySide && qa.find(snapBody,"snapshotDonutPlot").visible && qa.find(snapBody,"snapshotBarPlot").visible && !qa.find(snapBody,"snapshotChartTabs").visible && !categoryRows.interactive && categoryRows.height>=categoryRows.contentHeight',window='snapshotWindow',screenshot='snapshot-wide.png')
    add('reveal snapshot table for wheel input',eval='snapshotScroll.contentItem.contentY=Math.max(0,categoryTable.mapToItem(snapBody,0,0).y-snapshotScroll.availableHeight/2)')
    add('wheel over table scrolls whole snapshot',eval='var scrollBefore=snapshotScroll.contentItem.contentY;var statsBefore=qa.find(snapBody,"statCards").mapToItem(snapshotWindow.contentItem,0,0).y;qa.wheel(categoryTable,200,60,-400)',wait='snapshotScroll.contentItem.contentY>scrollBefore',assert_='categoryRows.contentY===0 && qa.find(snapBody,"statCards").mapToItem(snapshotWindow.contentItem,0,0).y<statsBefore',window='snapshotWindow',screenshot='snapshot-page-scroll.png')
    add('scroll snapshot to bottom',eval='snapshotScroll.contentItem.contentY=Math.max(0,snapshotScroll.contentHeight-snapshotScroll.availableHeight)')
    add('snapshot last row reachable',delay=200,assert_='categoryTable.mapToItem(snapshotWindow.contentItem,0,categoryTable.height).y<=snapshotWindow.height && categoryRows.contentY===0',window='snapshotWindow',screenshot='snapshot-bottom.png')
    add('narrow snapshot',eval='snapshotScroll.contentItem.contentY=0;snapshotWindow.width=760')
    add('narrow tabs align left',delay=200,assert_='!snapBody.sideBySide && qa.find(snapBody,"snapshotChartTabs").visible && qa.find(snapBody,"pieChartButton").x===0 && qa.find(snapBody,"snapshotDonutPlot").visible && !qa.find(snapBody,"snapshotBarPlot").visible',window='snapshotWindow',screenshot='snapshot-narrow-donut.png')
    add('switch snapshot bars',eval='qa.click(qa.find(snapshotWindow,"barChartButton"),-1,-1)',assert_='snapBody.chartMode==="bar" && qa.find(snapBody,"snapshotBarPlot").visible && !qa.find(snapBody,"snapshotDonutPlot").visible',window='snapshotWindow',screenshot='snapshot-narrow-bars.png')
    add('switch snapshot chart',eval='qa.click(qa.find(snapshotWindow,"pieChartButton"),-1,-1)',assert_='snapBody.chartMode==="pie"')
    add('snapshot donut screenshot',delay=200,window='snapshotWindow',screenshot='snapshot-donut.png')
    add('restore wide snapshot',eval='snapshotWindow.width=1280;snapshotScroll.contentItem.contentY=0')
    add('reveal snapshot detail tabs',delay=160,eval='snapshotScroll.contentItem.contentY=Math.max(0,categoryTable.mapToItem(snapBody,0,0).y-snapshotScroll.availableHeight/2)')
    add('switch snapshot detail tab',eval='var snapBody=qa.find(snapshotWindow,"snapshotBody");qa.click(qa.find(snapBody,"detailTab-ashmem"),-1,-1)',assert_='snapBody.detailIndex===1')
    add('snapshot detail screenshot',delay=300,window='snapshotWindow',screenshot='snapshot-detail.png')
    add('activate independent window',eval='var closingWindow=root.childWindows[1];closingWindow.raise();closingWindow.requestActivate()',wait='closingWindow.active')
    add('minimize independent window shortcut',eval='qa.key(closingWindow,77,67108864)',wait='closingWindow.visibility===3')
    add('restore independent window',eval='closingWindow.showNormal();closingWindow.raise();closingWindow.requestActivate()',wait='closingWindow.active')
    add('independent window close shortcut',eval='qa.key(closingWindow,87,'+str(67108864)+')',wait='root.childWindows.length===3',assert_='report.visible && compare.visible')
    add('narrow title and report',eval='report.raise();report.requestActivate();report.width=640;report.height=480;',delay=100)
    add('narrow screenshot',delay=200,wait='report.active',assert_='qa.find(report,"memoryPlot").width>200',window='report',screenshot='report-narrow.png')
    add('open narrow category list',eval='qa.click(qa.find(report,"categoriesButton"),-1,-1)',wait='qa.find(report,"categoriesPopup").opened',window='report',screenshot='categories-open.png')
    add('toggle category',eval='var categoryPopup=qa.find(report,"categoriesPopup");qa.click(qa.find(categoryPopup,"category-GL"),-1,-1)',assert_='qa.find(report,"memoryChart").hidden.indexOf("GL")>=0',window='report',screenshot='narrow-categories.png')
    add('close categories',eval='qa.key(report,16777216)',wait='!qa.find(report,"categoriesPopup").opened')
    add('open chart display options',eval='qa.click(qa.find(report,"displayOptionsButton"),-1,-1)',wait='qa.find(report,"displayOptions").opened')
    add('adjust tooltip background opacity',eval='var opacity=qa.find(report,"tooltipOpacity");qa.click(opacity,opacity.width*.45,opacity.height/2);qa.click(qa.find(report,"pointsSwitch"),-1,-1)',assert_='qa.find(report,"memoryChart").tooltipAlpha<.7 && qa.find(report,"memoryChart").points',window='report',screenshot='chart-display-options.png')
    add('close display options',eval='qa.key(report,16777216)',wait='!qa.find(report,"displayOptions").opened')
    add('restore report width preserves categories',eval='report.width=1280;report.height=840;',assert_='qa.find(report,"memoryChart").hidden.indexOf("GL")>=0')
    add('environment information',eval='qa.click(qa.find(report,"environmentButton"),-1,-1)',wait='qa.find(report,"environmentDialog").opened',window='report',screenshot='environment.png')
